    return { position: s[1], points: s[2], wins: wins[s[0]] || 0, driverId: lid, name: `${d[1]} ${d[2]}`, first: d[1], last: d[2], code: d[6], permNumber: undefined, teamId: t?.[0], team: t?.[1] };
