  Object.keys(H.r).forEach((y) => H.r[y].forEach((rc) => { if (rc[5] && rc[5][1] === ti) poles++; rc[4].forEach((row) => { if (row[1] === ti) { ys.add(+y); if (row[4] === '1') wins++; } }); }));
