  const byYear = {}; rows.forEach(({ year, row }) => { const y = (byYear[year] = byYear[year] || {}); const t = H.t[row[1]]; const k = t[0]; y[k] = y[k] || { teamId: k, team: t[1], races: 0, wins: 0 }; y[k].races++; if (row[4] === '1') y[k].wins++; });
