  years.forEach((y) => H.r[String(y)].forEach((rc) => { lastKey = `${y}-${rc[0]}`; rc[4].forEach((r) => { (per[r[0]] ||= []).push({ y, rd: rc[0], pos: /^\d+$/.test(String(r[4])) ? +r[4] : 99, pts: Number(r[5]) || 0, key: `${y}-${rc[0]}` }); }); }));
