    races.forEach(({ rc }) => { const r = rc[4].find((x) => x[0] === i); if (!r) return; starts++; const p = /^\d+$/.test(String(r[4])) ? +r[4] : 99; if (p === 1) w++; if (p <= 3) pod++; if (p < best) best = p; });
